#include <stdio.h>
#include <time.h>

int main(void) {
    clock_t start = clock();
    volatile unsigned long long sink = 0;
    for (unsigned long long i = 0; i < 1000000ULL; ++i) sink += i;
    clock_t end = clock();
    printf("CPU seconds: %.6f (sink=%llu)\n", (double)(end - start) / CLOCKS_PER_SEC, sink);
    return 0;
}
